"use client";

import React, { useState, useEffect, useRef } from 'react';
import * as XLSX from 'xlsx';
import Chart from 'chart.js/auto';
import './totp.css'; // Import file CSS yang baru dibuat

export default function TotpInventoryPage() {
    // --- STATE MANAGEMENT ---
    const [tokens, setTokens] = useState([]);
    const [stats, setStats] = useState({ available: 0, assigned: 0, suspended: 0, revoked: 0, expiringSoon: 0 });
    const [selectedTokens, setSelectedTokens] = useState(new Set());
    
    // Filters
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [vendorFilter, setVendorFilter] = useState('');
    const [batchFilter, setBatchFilter] = useState('');

    // Modals
    const [isImportModalOpen, setImportModalOpen] = useState(false);
    const [isDetailModalOpen, setDetailModalOpen] = useState(false);
    const [selectedTokenDetail, setSelectedTokenDetail] = useState(null);
    
    // Import State
    const [importFile, setImportFile] = useState(null);
    const [importVendor, setImportVendor] = useState('');
    const [importBatchId, setImportBatchId] = useState('');
    const [decryptionKey, setDecryptionKey] = useState('');
    const [importProgress, setImportProgress] = useState({ active: false, percent: 0, text: '' });

    // Toast State
    const [toasts, setToasts] = useState([]);

    // Chart Refs
    const vendorChartRef = useRef(null);
    const expiryChartRef = useRef(null);
    const vendorChartInstance = useRef(null);
    const expiryChartInstance = useRef(null);

    // --- 1. DATA FETCHING ---
    const fetchInventoryData = async () => {
        try {
            // Sesuaikan URL API dengan setup proxy Next.js Anda
            const response = await fetch('/api/admin/totp-inventory');
            const result = await response.json();

            if (result.success || result.tokens) {
                const mappedTokens = result.tokens.map(t => ({
                    serial: t.serialNumber,
                    status: t.status,
                    vendor: t.vendor,
                    batch: t.batchId,
                    user: t.user ? { name: t.user.fullName, id: t.user.id } : null,
                    expiry: t.expiryDate,
                    lastUsed: t.lastUsedAt ? new Date(t.lastUsedAt).toLocaleString('en-US') : null
                }));
                setTokens(mappedTokens);
                if(result.stats) setStats(result.stats);
            }
        } catch (err) {
            showToast('error', 'Connection Error', 'Gagal memuat data dari server');
        }
    };

    useEffect(() => {
        fetchInventoryData();
    }, []);

    // --- 2. CHART INITIALIZATION ---
    useEffect(() => {
        if (tokens.length === 0) return;

        const vendorCounts = { yubico: 0, feitian: 0, safenet: 0, other: 0 };
        tokens.forEach(t => {
            if(vendorCounts[t.vendor] !== undefined) vendorCounts[t.vendor]++;
            else vendorCounts.other++;
        });

        if (vendorChartInstance.current) vendorChartInstance.current.destroy();
        if (vendorChartRef.current) {
            vendorChartInstance.current = new Chart(vendorChartRef.current, {
                type: 'doughnut',
                data: {
                    labels: ['Yubico', 'Feitian', 'SafeNet', 'Other'],
                    datasets: [{
                        data: [vendorCounts.yubico, vendorCounts.feitian, vendorCounts.safenet, vendorCounts.other],
                        backgroundColor: ['#3b82f6', '#8b5cf6', '#10b981', '#64748b'],
                        borderWidth: 0
                    }]
                },
                options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'right' } } }
            });
        }

        // Cleanup
        return () => {
            if (vendorChartInstance.current) vendorChartInstance.current.destroy();
        };
    }, [tokens]);

    // --- 3. FILTERING LOGIC ---
    const filteredTokens = tokens.filter(token => {
        const matchesSearch = !searchQuery || 
            token.serial.toLowerCase().includes(searchQuery.toLowerCase()) ||
            (token.user && token.user.name.toLowerCase().includes(searchQuery.toLowerCase())) ||
            token.batch.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesStatus = !statusFilter || token.status === statusFilter;
        const matchesVendor = !vendorFilter || token.vendor === vendorFilter;
        const matchesBatch = !batchFilter || token.batch === batchFilter;
        return matchesSearch && matchesStatus && matchesVendor && matchesBatch;
    });

    // --- 4. IMPORT LOGIC ---
    const handleImportSubmit = async () => {
        if (!importVendor || !importBatchId || !decryptionKey || !importFile) {
            return showToast('warning', 'Incomplete Form', 'Mohon lengkapi semua data import.');
        }

        setImportProgress({ active: true, percent: 30, text: 'Uploading & Decrypting file...' });

        const formData = new FormData();
        formData.append('seedFile', importFile);
        formData.append('vendor', importVendor);
        formData.append('batchId', importBatchId);
        formData.append('decryptionKey', decryptionKey);

        try {
            const res = await fetch('/api/admin/totp-inventory/import', { method: 'POST', body: formData });
            const result = await res.json();

            setImportProgress({ active: true, percent: 100, text: 'Import complete!' });

            setTimeout(() => {
                setImportModalOpen(false);
                setImportProgress({ active: false, percent: 0, text: '' });
                if (result.success || result.message) {
                    showToast('success', 'Import Successful', result.message || 'Token berhasil diimport');
                    fetchInventoryData();
                } else {
                    showToast('error', 'Import Failed', result.error);
                }
            }, 1000);
        } catch (err) {
            showToast('error', 'Import Error', err.message);
            setImportProgress({ active: false, percent: 0, text: '' });
        }
    };

    // --- 5. EXPORT LOGIC ---
    const handleExport = () => {
        if (tokens.length === 0) return showToast('warning', 'Empty Data', 'Tidak ada data untuk diekspor');
        const exportData = tokens.map(t => ({
            'Serial Number': t.serial, 'Status': t.status, 'Vendor': t.vendor, 'Batch ID': t.batch,
            'Assigned User': t.user ? t.user.name : 'N/A', 'Expiry Date': new Date(t.expiry).toLocaleDateString()
        }));
        const worksheet = XLSX.utils.json_to_sheet(exportData);
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, "TOTP_Inventory");
        XLSX.writeFile(workbook, `TOTP_Inventory_${new Date().toISOString().slice(0,10)}.xlsx`);
        showToast('success', 'Export Started', 'File Excel berhasil diunduh');
    };

    // --- 6. UTILS ---
    const showToast = (type, title, message) => {
        const id = Date.now();
        setToasts(prev => [...prev, { id, type, title, message }]);
        setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
    };

    const toggleSelection = (serial) => {
        const newSet = new Set(selectedTokens);
        if (newSet.has(serial)) newSet.delete(serial);
        else newSet.add(serial);
        setSelectedTokens(newSet);
    };

    const capitalize = (str) => str.charAt(0).toUpperCase() + str.slice(1);
    const getInitials = (name) => name.split(' ').map(n => n[0]).join('').toUpperCase();

    // ==========================================
    // RENDER UI
    // ==========================================
    return (
        <div className="main-content">
            {/* Header */}
            <header className="header">
                <div className="header-title">
                    <h2>TOTP Token Inventory</h2>
                    <span className="badge">Hardware Tokens</span>
                </div>
                <div className="header-actions">
                    <button className="btn btn-secondary" onClick={handleExport}>
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                        Export
                    </button>
                    <button className="btn btn-primary" onClick={() => setImportModalOpen(true)}>
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
                        Import Batch
                    </button>
                </div>
            </header>

            {/* Content Area */}
            <div className="content-area">
                {/* Stats Grid */}
                <div className="stats-grid">
                    <div className="stat-card available">
                        <div className="stat-label">Available</div>
                        <div className="stat-value">{stats.available}</div>
                    </div>
                    <div className="stat-card assigned">
                        <div className="stat-label">Assigned</div>
                        <div className="stat-value">{stats.assigned}</div>
                    </div>
                    <div className="stat-card suspended">
                        <div className="stat-label">Suspended</div>
                        <div className="stat-value">{stats.suspended}</div>
                    </div>
                    <div className="stat-card revoked">
                        <div className="stat-label">Revoked</div>
                        <div className="stat-value">{stats.revoked}</div>
                    </div>
                    <div className="stat-card expired">
                        <div className="stat-label">Expiring Soon</div>
                        <div className="stat-value">{stats.expiringSoon}</div>
                    </div>
                </div>

                {/* Charts Row */}
                <div className="charts-row">
                    <div className="panel">
                        <div className="panel-header"><div className="panel-title">Inventory by Vendor</div></div>
                        <div className="chart-container"><canvas ref={vendorChartRef}></canvas></div>
                    </div>
                    <div className="panel">
                        <div className="panel-header"><div className="panel-title">Token Expiry Timeline</div></div>
                        <div className="chart-container"><canvas ref={expiryChartRef}></canvas></div>
                    </div>
                </div>

                {/* Token Table Panel */}
                <div className="panel">
                    <div className="panel-header">
                        <div className="panel-title">Token Inventory</div>
                        <button className="btn btn-secondary btn-sm" onClick={fetchInventoryData}>Refresh</button>
                    </div>
                    <div className="panel-body" style={{ paddingBottom: 0 }}>
                        <div className="filters-bar">
                            <div className="search-input">
                                <input type="text" placeholder="Search serial number..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
                            </div>
                            <select className="filter-select" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
                                <option value="">All Status</option>
                                <option value="available">Available</option>
                                <option value="assigned">Assigned</option>
                                <option value="suspended">Suspended</option>
                            </select>
                            <select className="filter-select" value={vendorFilter} onChange={(e) => setVendorFilter(e.target.value)}>
                                <option value="">All Vendors</option>
                                <option value="yubico">Yubico</option>
                                <option value="feitian">Feitian</option>
                                <option value="safenet">SafeNet</option>
                            </select>
                        </div>

                        <div className="table-container">
                            <table id="tokenTable">
                                <thead>
                                    <tr>
                                        <th className="checkbox-cell"></th>
                                        <th>Serial Number</th>
                                        <th>Status</th>
                                        <th>Vendor</th>
                                        <th>Batch ID</th>
                                        <th>Assigned To</th>
                                        <th>Expiry</th>
                                        <th>Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredTokens.length === 0 ? (
                                        <tr><td colSpan={8} style={{textAlign: 'center', padding: '20px'}}>No tokens found</td></tr>
                                    ) : (
                                        filteredTokens.map((token) => (
                                            <tr key={token.serial}>
                                                <td className="checkbox-cell">
                                                    <div className={`checkbox ${selectedTokens.has(token.serial) ? 'checked' : ''}`} onClick={() => toggleSelection(token.serial)}>
                                                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><polyline points="20 6 9 17 4 12"/></svg>
                                                    </div>
                                                </td>
                                                <td><span className="serial-number">{token.serial}</span></td>
                                                <td><span className={`status-badge status-${token.status}`}>{capitalize(token.status)}</span></td>
                                                <td><span className="vendor-badge">{capitalize(token.vendor)}</span></td>
                                                <td><span className="batch-badge">{token.batch}</span></td>
                                                <td>
                                                    {token.user ? (
                                                        <div className="user-cell">
                                                            <div className="user-avatar">{getInitials(token.user.name)}</div>
                                                            <div className="user-info">
                                                                <span className="user-name">{token.user.name}</span>
                                                                <span className="user-id">{token.user.id}</span>
                                                            </div>
                                                        </div>
                                                    ) : <span style={{color: 'var(--text-tertiary)'}}>—</span>}
                                                </td>
                                                <td><span className="expiry-date">{new Date(token.expiry).toLocaleDateString()}</span></td>
                                                <td>
                                                    <button className="btn btn-secondary btn-sm" onClick={() => { setSelectedTokenDetail(token); setDetailModalOpen(true); }}>
                                                        View
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>

            {/* Import Modal */}
            <div className={`modal-overlay ${isImportModalOpen ? 'active' : ''}`}>
                <div className="modal">
                    <div className="modal-header">
                        <h3>Import Token Batch</h3>
                        <button className="modal-close" onClick={() => setImportModalOpen(false)}>✕</button>
                    </div>
                    <div className="modal-body">
                        <div className="form-group">
                            <label className="form-label">Vendor</label>
                            <select className="form-input" value={importVendor} onChange={(e) => setImportVendor(e.target.value)}>
                                <option value="">Select vendor...</option>
                                <option value="yubico">Yubico</option>
                                <option value="feitian">Feitian</option>
                            </select>
                        </div>
                        <div className="form-group">
                            <label className="form-label">Batch ID</label>
                            <input type="text" className="form-input" value={importBatchId} onChange={(e) => setImportBatchId(e.target.value)} placeholder="e.g., BATCH-2024-004" />
                        </div>
                        <div className="form-group">
                            <label className="form-label">Seed File (Excel/CSV)</label>
                            <input type="file" className="form-input" onChange={(e) => setImportFile(e.target.files[0])} accept=".xlsx,.csv" />
                        </div>
                        <div className="form-group">
                            <label className="form-label">Decryption Key (Admin)</label>
                            <input type="password" className="form-input" value={decryptionKey} onChange={(e) => setDecryptionKey(e.target.value)} placeholder="AES Secret Key" />
                        </div>
                        
                        {importProgress.active && (
                            <div className="import-progress" style={{ display: 'block' }}>
                                <div className="progress-bar">
                                    <div className="progress-fill" style={{ width: `${importProgress.percent}%` }}></div>
                                </div>
                                <div className="progress-text">
                                    <span>{importProgress.text}</span>
                                    <span>{importProgress.percent}%</span>
                                </div>
                            </div>
                        )}
                    </div>
                    <div className="modal-footer">
                        <button className="btn btn-secondary" onClick={() => setImportModalOpen(false)}>Cancel</button>
                        <button className="btn btn-primary" onClick={handleImportSubmit}>Import</button>
                    </div>
                </div>
            </div>

            {/* Toasts Container */}
            <div className="toast-container">
                {toasts.map(toast => (
                    <div key={toast.id} className="toast">
                        <div className={`toast-icon ${toast.type}`}>{toast.type === 'success' ? '✓' : '⚠'}</div>
                        <div className="toast-content">
                            <div className="toast-title">{toast.title}</div>
                            <div className="toast-message">{toast.message}</div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}